package com.sigo.asistencia.repository; import com.sigo.asistencia.entity.Trabajador; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface TrabajadorRepository extends JpaRepository<Trabajador,Long>{ Optional<Trabajador> findByCodigo(Integer codigo); List<Trabajador> findByActivoTrueOrderByNombreCompletoAsc(); List<Trabajador> findByPuestoNombreIgnoreCaseAndActivoTrueOrderByNombreCompletoAsc(String puesto); }
